import json,html,collections,subprocess
from pathlib import Path
R=Path('/private/tmp/rosso-tau2-study'); D=R/'data/tau2'; OUT=Path(__file__).parent
load=lambda p:json.loads(p.read_text())
esc=lambda x:html.escape(str(x))
pretty=lambda x:esc(json.dumps(x,ensure_ascii=False,indent=2))
base=load(D/'domains/retail/tasks.json'); split=load(D/'domains/retail/split_tasks.json'); subset=load(D/'task_subsets/retail_50.json')['task_ids']; voice=load(D/'domains/retail/tasks_voice.json')['configs']
sha=subprocess.check_output(['git','-C',str(R),'rev-parse','HEAD'],text=True).strip(); link='https://github.com/sierra-research/tau2-bench/blob/'+sha+'/'
labels={'cancel_pending_order':'Cancel pending orders','exchange_delivered_order_items':'Exchange delivered items','return_delivered_order_items':'Return delivered items','modify_pending_order_items':'Modify pending order items','modify_pending_order_address':'Modify order shipping address','modify_pending_order_payment':'Modify order payment method','modify_user_address':'Modify user default address','transfer_to_human_agents':'Transfer to human agents'}
writes=set(labels)-{'transfer_to_human_agents'}
effects={'cancel_pending_order':'Sets status to cancelled and records the reason and refund transactions; gift-card refunds also change balances.','exchange_delivered_order_items':'Sets status to exchange requested and records old items, new items, payment method, and price difference. This records a request, not completed physical fulfillment or refund settlement.','return_delivered_order_items':'Sets status to return requested and records return items and refund method. This records a return request.','modify_pending_order_items':'Replaces items, records the price-difference transaction and applicable gift-card balance changes, and sets status to pending (item modified). The precise final state follows the tool implementation at this revision.','modify_pending_order_address':'Updates the order address; this does not automatically update the user default address.','modify_user_address':'Updates the user default address; this does not automatically update existing orders.','modify_pending_order_payment':'Updates order payment transactions and applicable gift-card balances.'}
sets=[('base','Base tasks','data/tau2/domains/retail/tasks.json',base,load(D/'domains/retail/db.json'))]
sets.append(('en','English multilingual variant','data/tau2/multilingual/en/retail_tasks_en.json',load(D/'multilingual/en/retail_tasks_en.json'),load(D/'domains/retail/db.json')))
for lang in ['zh','es','pt','hi','ko']:
 p=D/f'multilingual/{lang}/regional/retail.json';d=load(p);sets.append((lang,f'{lang} regional variant',str(p.relative_to(R)),d['tasks'],d['database']))
issues=collections.defaultdict(list)
for p in (D/'domains/retail/task_issues').glob('*.json'):
 d=load(p);issues[str(d['task_id'])].append((str(p.relative_to(R)),d))
counts=collections.Counter()
for t in base:
 for n in set(a['name'] for a in t['evaluation_criteria']['actions']):
  if n in labels:counts[labels[n]]+=1
no_write=sum(not any(a['name'] in writes for a in t['evaluation_criteria']['actions']) for t in base)
parts=['''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>tau2 Retail Tasks and Scoring Criteria</title><style>body{margin:0;background:#f5f6f2;color:#183139;font:16px/1.75 system-ui,-apple-system,sans-serif}main{max-width:1120px;margin:auto;padding:40px 28px}h1{font-size:36px}h2{margin-top:38px}h3{margin:0}a{color:#007773}article,section{background:white;padding:24px;border:1px solid #dce4df;border-radius:12px;margin:16px 0}summary{cursor:pointer;font-weight:650}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f1f4f3;padding:14px;border-radius:7px;font:13px/1.65 ui-monospace,monospace}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #dde4e1;padding:9px;text-align:left;vertical-align:top}.tag{display:inline-block;padding:3px 9px;background:#e1efeb;border-radius:5px;margin:5px;font-size:13px}.warn{border-left:4px solid #b47920;padding:10px 16px;background:#fff8e8}.bar{position:sticky;top:0;background:#f5f6f2;padding:12px 0;z-index:1}input,select,button{font:inherit;padding:9px;border:1px solid #aebfbb;border-radius:6px}input{width:45%}.muted{color:#607077}.goal{font-size:17px}li{margin:5px 0}@media print{.bar{display:none}body{background:white}article{break-inside:avoid}main{max-width:none;padding:0}details:not([open]){display:none}}</style><main><h1>tau2 Retail Tasks and Scoring Criteria</h1>''']
parts.append(f'<p>Repository revision used for the study notes and presentation: <code>{sha}</code>. This catalog includes all 114 base tasks and 300 English and regionalized task definitions. These variants do not represent 414 independent business scenarios. Explanations and navigation are in English; repository task text and localized entity values are preserved verbatim. Search by order, product, tool, assertion, or task ID.</p>')
parts.append('''<section><h2>How scoring works</h2><ol><li>The user simulator reads user_scenario. The agent learns the request through conversation; hidden reference actions are not supplied as answers to the agent.</li><li>DB check: replay the actual trajectory and reference actions separately from the same initial state, then compare database hashes. A match scores 1; otherwise 0. Reference read calls do not imply that every lookup must occur in exactly that order.</li><li>NL_ASSERTION check: an LLM judges each natural-language assertion against the trajectory. All must pass for a score of 1. Empty assertions contribute 1.</li><li>In the default ALL evaluation mode, components selected by reward_basis are multiplied. Premature termination scores 0. Changing evaluation_type, for example to force ACTION checks, changes the scoring semantics.</li></ol><p class="warn">Of 114 base tasks, 112 use DB + NL_ASSERTION; tasks 33 and 34 use DB only. Forty tasks have nonempty NL assertions; 72 select NL but leave the assertions empty. After normal termination, 74 tasks therefore depend primarily on DB checks. No base task includes ACTION or COMMUNICATE in reward_basis. Logged action_checks or populated communicate_info do not by themselves contribute to the final reward.</p><p>When there are no reference writes, the expected DB state is normally unchanged. Without effective NL assertions, final-state checks provide weak coverage of answer quality. Authentication, confirmation, privacy, and policy compliance remain requirements, but each task does not necessarily contain assertions for them. Passing a task does not establish complete compliance.</p></section>''')
parts.append('<section><h2>Task sets and categories</h2><p>Base tasks: 74 train / 40 test; the base split contains all 114 tasks. retail_50 is a stratified sample of 50 tasks based on write profiles, not 50 additional scenarios. Voice configurations cover 114 base IDs and vary audio and interaction conditions rather than defining new business answers.</p><table><tr><th>Reference-action categories (may overlap)</th><th>Task count</th></tr>')
for k,v in counts.items():parts.append(f'<tr><td>{k}</td><td>{v}</td></tr>')
parts.append(f'<tr><td>No reference DB writes (including information requests or transfers)</td><td>{no_write}</td></tr></table><p>Regional variants change names, addresses, products, amounts, and other values. Use the matching database and reference arguments rather than applying base-task answers unchanged. The default view shows 114 base tasks; the menu also exposes all variants.</p></section>')
parts.append('''<section><h2>Shared business rules and scoring boundaries</h2><ul><li>Authenticate using email or name and ZIP code; handle information only for that user.</li><li>Explain the action and obtain explicit confirmation before updating the database. Collect all item changes for an order before an exchange or item modification.</li><li>Cancellation and modification apply to pending orders; returns and exchanges apply to delivered orders. Replacement items must be available variants of the same product.</li><li>Cancellation reasons are limited to no longer needed or ordered by mistake. Refunds and price differences must satisfy payment-method and gift-card balance constraints.</li><li>An order shipping address and a user default address are separate state. A return or exchange request is distinct from completed fulfillment.</li></ul><p>Expected state changes below explain the tool implementation. The DB evaluator compares complete final environment state, not just the listed fields; unintended changes can also cause failure. This is a task catalog, not a report of newly executed model evaluations.</p></section>''')
parts.append('<div class="bar"><input id="q" placeholder="Search tasks, orders, tools, products, assertions…"><select id="set"><option value="base">Base tasks 114</option value="all">All definitions 414</option value="en">English variants 50</option value="zh">Chinese regional variants 50</option value="es">Spanish regional variants 50</option value="pt">Portuguese regional variants 50</option value="hi">Hindi regional variants 50</option value="ko">Korean regional variants 50</option></select> <select id="grade"><option value="all">All scoring types</option><option value="nl">With NL assertions</option><option value="db">No effective NL assertions</option></select><span id="count"></span></div><div id="tasks">')
for key,label,source,tasks,db in sets:
 products=db.get('products',{}); itemmap={iid:(p['name'],v) for p in products.values() for iid,v in p.get('variants',{}).items()}
 for t in tasks:
  tid=str(t['id']);e=t.get('evaluation_criteria') or {};acts=e.get('actions') or [];nl=e.get('nl_assertions') or [];basis=e.get('reward_basis',[]);ws=[a for a in acts if a['name'] in writes];cats=list(dict.fromkeys(labels[a['name']] for a in acts if a['name'] in labels)) or ['Lookups and information requests'];title=' / '.join(cats);inst=t['user_scenario']['instructions'];cid=tid.split('_')[0]
  parts.append(f'<article data-set="{key}" data-nl="{"nl" if nl else "db"}" id="{key}-{tid}"><h3>{esc(label)} · Task {esc(tid)} · {esc(title)}</h3>')
  tags=[str(x) for x in basis]
  if key=='base':tags += [('train' if tid in split['train'] else 'test'),('In retail_50 subset' if tid in subset else 'Outside retail_50')]
  parts.append(''.join(f'<span class="tag">{esc(x)}</span>' for x in tags))
  if isinstance(inst,dict):
   parts.append(f'<h4>Task and user goal (repository text)</h4><p class="goal">{esc(inst.get("reason_for_call",""))}</p>')
   for field,cn in [('task_instructions','Interaction instructions'),('known_info','Known identity and information'),('unknown_info','Unknown information')]:
    if inst.get(field):parts.append(f'<p><b>{cn}: </b>{esc(inst[field])}</p>')
  else:parts.append(f'<p>{esc(inst)}</p>')
  if t['user_scenario'].get('persona'):parts.append(f'<p>Persona: {esc(t["user_scenario"]["persona"])}</p>')
  parts.append('<h4>How this task is evaluated</h4>')
  if not ws:parts.append('<p>There are no reference database writes: the expected DB result is the unchanged state produced by the reference flow. This alone does not verify the answer content.</p>')
  else:
   parts.append('<ol>')
   for a in ws:
    args=a['arguments'];target=args.get('order_id') or args.get('user_id','');parts.append(f'<li><b>{labels[a["name"]]} {esc(target)}</b>: {effects[a["name"]]}<pre>{pretty(args)}</pre>')
    desc=[]
    for field in ['item_ids','new_item_ids']:
     for iid in args.get(field,[]):
      if iid in itemmap:
       name,v=itemmap[iid];desc.append(f'{field}: {iid} → {name}; options {json.dumps(v.get("options"),ensure_ascii=False)}; catalog price {v.get("price")}')
    if desc:parts.append('<p class="muted">'+'<br>'.join(map(esc,desc))+'<br>Catalog prices help identify variants. Historical purchase prices may differ, so these are not necessarily refund amounts.</p>')
    parts.append('</li>')
   parts.append('</ol>')
  if nl:parts.append('<p><b>Required natural-language assertions:</b></p><ol>'+''.join('<li>'+esc(n)+'</li>' for n in nl)+'</ol>')
  else:parts.append('<p><b>Natural-language assertions:</b>No nonempty assertions are configured. If the basis includes NL_ASSERTION, this component contributes 1.</p>')
  parts.append('<p><b>Scoring in default ALL mode:</b>'+('Scores 1 after normal termination only if the DB check and every listed NL assertion pass.' if nl and 'NL_ASSERTION' in basis else 'Scores 1 after normal termination when the DB final state matches the reference final state, under the selected task basis.')+'</p>')
  if e.get('communicate_info'):parts.append('<p><b>Original communicate_info:</b>'+esc(json.dumps(e['communicate_info'],ensure_ascii=False))+'. '+('COMMUNICATE is included in the basis.' if 'COMMUNICATE' in basis else 'COMMUNICATE is not in this task basis. This list is not automatically an independently enforced scoring check.')+'</p>')
  parts.append('<details><summary>Complete reference tool calls (including reads; not the only valid call order)</summary><ol>')
  for a in acts:parts.append(f'<li><code>{esc(a["name"])}</code><pre>{pretty(a["arguments"])}</pre></li>')
  parts.append('</ol></details>')
  if key=='base' and cid in issues:
   parts.append('<details><summary>Historical task issue records in the repository</summary>')
   for p,d in issues[cid]:parts.append(f'<p><a href="{link+p}">{esc(p.split("/")[-1])}</a>: Recorded score: {esc(d.get("reward_info",{}).get("reward"))}. This is a historical run, not evidence of a defect that necessarily occurs in every version.</p>')
   parts.append('</details>')
  parts.append(f'<details><summary>Complete task definition (including initial state and original scoring configuration)</summary><pre>{pretty(t)}</pre></details><p class="muted"><a href="{link+source}">Source file</a> · Find ID in file: {esc(tid)}</p></article>')
parts.append('</div><section><h2>Source references and scope</h2><ul>')
for p in ['data/tau2/domains/retail/tasks.json','data/tau2/domains/retail/split_tasks.json','data/tau2/domains/retail/policy.md','data/tau2/task_subsets/retail_50.json','data/tau2/domains/retail/tasks_voice.json','src/tau2/domains/retail/tools.py','src/tau2/evaluator/evaluator.py','src/tau2/evaluator/evaluator_env.py','src/tau2/evaluator/evaluator_nl_assertions.py']:
 parts.append(f'<li><a href="{link+p}">{p}</a></li>')
parts.append('</ul><p>Scope: retail business benchmark tasks in this repository. Framework unit tests, historical model results, and audio perturbation settings are not counted as additional business tasks. This catalog is pinned to the stated commit.</p></section></main><script>const cards=[...document.querySelectorAll("article")];function filter(){let q=document.querySelector("#q").value.toLowerCase(),s=document.querySelector("#set").value,g=document.querySelector("#grade").value,n=0;cards.forEach(c=>{let show=(s==="all"||c.dataset.set===s)&&(g==="all"||c.dataset.nl===g)&&c.textContent.toLowerCase().includes(q);c.hidden=!show;if(show)n++});document.querySelector("#count").textContent=" Showing "+n+" entries"}document.querySelectorAll("input,select").forEach(e=>e.addEventListener("input",filter));filter();</script></html>')
out=OUT/'tau2-retail-all-tasks-and-grading.en.html';out.write_text('\n'.join(parts));assert len(base)==114 and len(set(t['id'] for t in base))==114;assert sum(len(x[3]) for x in sets)==414
print(json.dumps({'file':str(out.resolve()),'base':len(base),'all_definitions':sum(len(x[3]) for x in sets),'nonempty_nl':sum(bool(t['evaluation_criteria'].get('nl_assertions')) for t in base),'bytes':out.stat().st_size,'categories':counts},ensure_ascii=False,indent=2))
